INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('e5444dd8-80b1-590b-89c8-a41c28a5c4a7', '253ab84b-cde9-51ca-a335-bf2e720e7d51', 'en', $h$Diaphragm Pump$h$, $h$diaphragm-pump$h$, $h$Diaphragm Pump – Flexibility and Reliability in Industrial Liquid Transfer$h$, $h$<div> <p><strong>Diaphragm pumps</strong> are positive displacement pumps that transfer liquid without mechanical contact by means of an elastic diaphragm, delivering high efficiency and durability in industrial processes. They stand out for maintaining performance even with fluids containing dust, dirt and particles.</p><p>These pumps offer the ideal solution for the safe and controlled handling of <strong>high-viscosity, abrasive or contaminated liquids</strong>. They are designed to maximize liquid transfer line safety in marine and industrial environments.</p> </div><div> <p><strong>HD Marine diaphragm pumps</strong>;</p><ul><li>Provide highly efficient positive displacement for a <strong>more stable flow</strong></li><li>Deliver <strong>long-lasting performance</strong> when handling abrasive and contaminated liquids</li><li>Build confidence on your production line with a <strong>robust and durable construction</strong> suited to marine and industrial environments</li></ul> </div>$h$, $h$<div> <p>Diaphragm pumps are used particularly in:</p><ul><li>Chemical and petrochemical plants</li><li>Food and pharmaceutical production lines</li><li>Wastewater and filtration facilities</li><li>Paint, printing and solvent transfer applications</li><li>Marine machinery</li></ul><p>delivering reliable performance across a wide variety of industrial and marine applications.</p> </div>$h$, $h$Diaphragm Pump | HD Marine$h$, $h$Diaphragm pumps are positive displacement pumps that transfer liquid without mechanical contact by means of an elastic diaphragm, delivering high…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('5b6b7aa4-b1b4-5ca7-980b-86143d45275e', 'a1f2922c-2b29-5af3-a1f2-37ea546d8294', 'en', $h$How does a diaphragm pump work?$h$, $h$<div> <p>Liquid is drawn in and discharged by the back-and-forth movement of a flexible diaphragm; there is no mechanical friction with the fluid.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('8152185f-4cc1-5487-af22-0dba70354d6c', '0ef27e6e-dc8f-5ed2-a7a7-84bc36089eda', 'en', $h$For which liquids is it preferred?$h$, $h$<div> <p>It is effective with particle-laden, abrasive, chemical or soluble liquids.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('cfa81648-df02-585f-b2b6-30ddbb82fb8d', '95309ff1-b960-57d1-bafc-29901a482bc1', 'en', $h$What is the difference between a diaphragm pump and a centrifugal pump?$h$, $h$<div> <p>Diaphragm pumps move liquid in a fixed volume via positive displacement, while centrifugal pumps convey the fluid using centrifugal force.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('a463d7f3-8fbe-5cc3-898d-c9e3b424f6b8', 'd0d30ee7-e267-5637-9d2a-343089fd5d18', 'en', $h$In which industries is it used in Turkey?$h$, $h$<div> <ul><li>It is common in chemical, paint and solvent, food and pharmaceutical, wastewater, marine and industrial facilities.</li></ul> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('85db65fb-1583-5ade-b123-28b4d4555393', '0de57938-4e61-5dce-9e4f-666656979eda', 'en', $h$Gear Pump$h$, $h$gear-pump$h$, $h$Gear Pump – Industrial Liquid Transfer Solutions$h$, $h$<div> <p><strong>Gear pumps</strong> are mechanical pumps that, thanks to their positive displacement operation, deliver a fixed amount of liquid per revolution and are frequently preferred in industrial systems. With these characteristics, they offer high performance and reliability, especially in the transfer of viscous (thick) liquids.</p><p>Gear pumps are the ideal solution for <strong>high-pressure transfer</strong>, <strong>low flow rate applications</strong> and <strong>systems requiring continuous flow control</strong>. By means of the gear wheels inside, these pumps draw in the liquid, pressurize it and deliver it steadily into the system line.</p><p>HD Marine gear pumps provide effectiveness in a variety of applications, from industrial facilities to production lines, with the capacity to transfer liquids across a wide viscosity range without problems.</p> </div><div> <p>✔ <strong>Constant flow rate:</strong> Delivers the same volume of liquid per revolution. <br/>✔ <strong>High viscosity compatibility:</strong> Suitable for oils, resins, chemicals and thick liquids. <br/>✔ <strong>High efficiency at low speed:</strong> Achieves the desired pressure and flow rate even at low motor speeds. <br/>✔ <strong>Reliable performance:</strong> Offers continuous and stable operation in industrial processes.</p> </div>$h$, $h$<div> <p>Gear pumps are used effectively in production facilities, chemical and petrochemical lines, lubrication systems, panel and hydraulic circuits, and in all industrial applications requiring viscous liquid transfer.</p> </div>$h$, $h$Gear Pump | HD Marine$h$, $h$Gear pumps are mechanical pumps that, thanks to their positive displacement operation, deliver a fixed amount of liquid per revolution and are frequently…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('e115a237-8b9b-5d7f-bdf4-13d5939871d8', '00597b28-bc2a-551b-a837-10d36a33ec60', 'en', $h$What is a gear pump used for?$h$, $h$<div> <p>Gear pumps draw in and discharge liquid at a fixed volume by means of gears, providing a smooth transfer.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('c3fd8fd0-0c1b-58f5-800d-774440b2b858', 'b345ab44-23dd-57b8-a64a-664822710a70', 'en', $h$With which liquids is it used?$h$, $h$<div> <p>It is effective with oils, resins, chemical liquids and high-viscosity fluids.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('7cc5c6c7-ba7a-5de9-82e0-a80fe1a5f8b7', 'b13820c3-1c22-547c-857a-4d31f01fcd1b', 'en', $h$What is the difference between a gear pump and a centrifugal pump?$h$, $h$<div> <p>Gear pumps provide fixed-displacement flow; centrifugal pumps generate flow through pressure differential.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('b944c84b-388f-54cd-908e-99ed517a6b54', 'd5901428-7bb2-5759-aeb0-7732a64fb61b', 'en', $h$Blower$h$, $h$blower$h$, $h$Industrial Blower – Powerful Air & Gas Transfer Solutions$h$, $h$<div> <p>A <strong>blower</strong> is an industrial air <strong>blowing and vacuum device</strong> that draws in air or gas at high flow rates and within a specific pressure range and delivers it to the outlet. It plays an active role in applications such as oxygenation of industrial processes, ventilation, drying, supplying compressed air or gas evacuation. Blowers generate higher pressure and a more controllable flow rate than fans, which is why they are preferred in many fields such as HVAC, treatment plants, pneumatic conveying and process equipment.</p> </div><div> <p><strong>✔️ Why HD Marine Blowers?</strong></p><p>HD Marine blowers:</p><ul><li>Deliver <strong>energy-efficient performance</strong></li><li>Are durable with <strong>low vibration and long service life</strong></li><li>Offer suitable options for different <strong>flow rates and pressure levels</strong></li><li>Reduce operating costs with <strong>easy installation and maintenance</strong></li></ul><p>These characteristics make blowers a reliable solution within industrial air handling and process equipment.</p> </div><div> <p>✔ <strong>High air / gas flow rate:</strong> Provides large-volume airflow <br/>✔ <strong>Pressure boosting capacity:</strong> Generates higher pressure than fans <br/>✔ <strong>Air transfer and vacuum applications:</strong> Can be used in both blowing and suction directions <br/>✔ <strong>Motor-controlled air intake:</strong> Stable performance thanks to the electric motor<br/>✔ <strong>Various types:</strong> Compatible with centrifugal, rotary or positive displacement models <br/>✔ <strong>Durable housing:</strong> Suited to industrial operating conditions</p> </div>$h$, NULL, $h$Blower | HD Marine$h$, $h$A blower is an industrial air blowing and vacuum device that draws in air or gas at high flow rates and within a specific pressure range and delivers it…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('9dc18c89-b9d3-5da8-83c6-7b5ae9907e20', '0a5cc4ab-a5f1-59b5-b224-1a6c6c194ac4', 'en', $h$What is a blower?$h$, $h$<div> <p>A blower is an industrial air/gas transfer device that draws in air or gas at high flow rates and specific pressure values and delivers it to the outlet.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('fdc7c462-881f-5d94-a9a8-f2dfa4c4c738', '0b7a55a8-5048-5a01-89c5-054a9ce08b4e', 'en', $h$What is the difference between a blower and a fan?$h$, $h$<div> <p>Fans generally provide low-pressure air circulation, while blowers are performance-oriented with higher pressure and a controllable flow rate.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('93c844de-4d30-5083-8f2b-703ea6bf3064', '8d96907e-06a0-5227-84e6-401aa535cc4e', 'en', $h$In which applications is it used?$h$, $h$<div> <p>It is used in ventilation, pneumatic conveying, drying, wastewater treatment and marine air evacuation processes.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('fac4f249-eda2-5344-ac5a-418f62bedc12', '8ca628ba-7681-5d8f-8030-dfff77071760', 'en', $h$What should be considered when selecting a blower?$h$, $h$<div> <p>The required airflow, desired pressure level, ambient temperature and motor power are important criteria in blower selection.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('e06fe56e-7575-51b9-b85c-19b823f2754a', '94151aad-5d35-5bc5-b797-07b8775f2c27', 'en', $h$Magnetic Drive Acid Pumps$h$, $h$magnetic-drive-acid-pumps$h$, $h$Magnetic Drive Acid Pump – Reliable Transfer for Corrosive Liquids$h$, $h$<div> <p>Magnetic drive acid pumps are <strong>magnetically coupled positive displacement pumps specially built for handling acids, chemicals and corrosive liquids</strong>. By using a magnetic coupling instead of a mechanical seal, they maximize sealing performance and <strong>offer superior resistance to contaminants and abrasive fluids</strong>.</p><p>HD Marine magnetic drive acid pumps deliver <strong>high performance and durability</strong> across a wide range of uses, particularly <strong>from laboratories to production lines</strong>, from chemical plants to marine applications.</p> </div><div> <ul><li><p>✔ <strong>High chemical resistance:</strong> Operates with harsh liquids over long periods<br/>✔ <strong>Leak-free performance:</strong> Safe transfer thanks to the magnetic coupling<br/>✔ <strong>Easy installation:</strong> User-friendly mounting design<br/>✔ <strong>Long-life construction:</strong> High durability with minimal maintenance</p></li></ul> </div>$h$, $h$<div> <p>HD Marine magnetic drive acid pumps are an effective solution particularly in:</p><ul><li>Chemical production plants</li><li>Paint and solvent lines</li><li>Water and wastewater treatment</li><li>Acid/alkali transfer systems</li><li>Marine and industrial processes</li></ul><p>and in all applications <strong>requiring the safe handling of corrosive and abrasive fluids</strong>.</p> </div>$h$, $h$Magnetic Drive Acid Pumps | HD Marine$h$, $h$Magnetic drive acid pumps are magnetically coupled positive displacement pumps specially built for handling acids, chemicals and corrosive liquids . By…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('cf6cbcfe-5679-55be-967b-83081c197f44', 'e2b38441-f993-5429-820e-3dd9699be755', 'en', $h$What is a magnetic drive acid pump?$h$, $h$<div> <p>It is a magnetically coupled positive displacement pump that provides leak-free transfer by using a magnetic drive instead of a mechanical seal.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('829f019d-d509-5f7d-9945-73c0537480de', '04a0dd5d-dd6b-5f8e-9618-2500aea3e365', 'en', $h$Is it suitable for chemical liquids?$h$, $h$<div> <p>Yes, it has been developed for the transfer of acids, alkalis and chemical reaction liquids.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('fc435b67-71f2-5837-a071-2988eaf7e324', '8523b925-b1c8-5ad0-bbd4-031057225675', 'en', $h$Why is no packing used?$h$, $h$<div> <p>Thanks to the magnetic coupling, the need for packing is reduced, providing sealing and maintenance advantages.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('1bde2054-115f-5a81-a544-b0380a4dc883', '6c718d69-d859-506b-84d5-59fbac45353e', 'en', $h$Where should it be used?$h$, $h$<div> <p>It is preferred in chemical plants, water treatment, paint lines and industrial processes.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('426a0461-680f-5925-9907-ae54aaf1b89b', '8f6fe15a-82df-5840-bd1f-0374353b4006', 'en', $h$Drum Pump$h$, $h$drum-pump$h$, $h$Drum Pump – A Practical Solution for Industrial Liquid Transfer$h$, $h$<div> <p><strong>Drum pumps</strong> are industrial equipment that enable the fast, controlled and ergonomic transfer of liquids from drums, jerry cans and cylindrical storage tanks. They deliver ideal performance in the handling of oils, chemicals, solvents, fuels and other fluids.</p><p>HD Marine drum pumps, with their durable construction, easy installation and broad application compatibility, are a reliable liquid transfer solution in both industrial facilities and marine processes.</p> </div><div> <p>✔ <strong>Practical installation:</strong> Suitable for various drum diameters<br/>✔ <strong>Durable construction:</strong> Materials with high chemical and solvent resistance<br/>✔ <strong>Various drive options:</strong> Manual, electric or pneumatic operation<br/>✔ <strong>Easy to use:</strong> Fast transfer with an ergonomic pump design<br/>✔ <strong>Broad application compatibility:</strong> Transfer of oil, fuel, chemicals, acids and alkalis</p> </div>$h$, NULL, $h$Drum Pump | HD Marine$h$, $h$Drum pumps are industrial equipment that enable the fast, controlled and ergonomic transfer of liquids from drums, jerry cans and cylindrical storage…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('48afea4d-efd2-5c98-9128-a0884291c337', '5dbaab34-afd1-531c-8166-d0e7ca651ab9', 'en', $h$What is a drum pump?$h$, $h$<div> <p>A drum pump is a special transfer pump that can dispense liquids from drums, jerry cans and tanks in an ergonomic and controlled manner.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('834326b0-66c3-5a3e-8de1-d37f1649a17d', '051d3b1c-196f-553f-9b22-98bfb7353b9b', 'en', $h$With which liquids can it be used?$h$, $h$<div> <p>Suitable models are available for oils, chemicals, solvents, fuels and various fluid types.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('4f927d11-7c76-573a-8375-eeda52c8c361', '0c9e1a01-b473-50cb-a9a3-5b496c1dacba', 'en', $h$What is the advantage of an electric drum pump?$h$, $h$<div> <p>Electric models provide faster transfer with less effort; they are suitable for large-volume storage.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('b993aef7-3242-5763-b72f-87d8ac603e57', '467085c4-2d6b-5767-8bd9-364c6770fbce', 'en', $h$How is the pump material selected?$h$, $h$<div> <p>The body and gasket materials (PP, aluminum, stainless steel, Viton, etc.) should be selected according to the chemical nature of the liquid to be handled.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('2cd7692c-4360-5aa1-9a49-065b9bf674ca', 'dafeaf56-2575-5e8d-82f5-c1a62bf5b04a', 'en', $h$Vacuum Pump$h$, $h$vacuum-pump$h$, $h$Vacuum Pump – A Powerful Solution for Effective Air/Void Control$h$, $h$<div> <p><strong>Vacuum pumps</strong> create negative pressure in a system by extracting the air or gas molecules within it. In this way, they deliver reliable performance in critical industrial applications such as <strong>creating a vacuum environment, gas evacuation and discharging ambient air</strong>. They are widely used in industry, chemicals, laboratories, production lines, packaging and process control systems.</p><p>HD Marine vacuum pumps, with their durable construction, precise suction power and high efficiency, <strong>deliver effective results even under continuous operating conditions.</strong></p> </div><div> <p>✔ <strong>High suction capacity:</strong> Stable and fast evacuation<br/>✔ <strong>Energy saving:</strong> Low energy consumption in long-term use<br/>✔ <strong>Broad compatibility:</strong> Integrates with different industry types<br/>✔ <strong>User-friendly design:</strong> Easy installation and maintenance</p> </div>$h$, $h$<div> <p>HD Marine vacuum pumps are suitable particularly for:</p><ul><li>Industrial process lines</li><li>Laboratory applications</li><li>Packaging machines</li><li>Chemical plants</li><li>HVAC and drying systems</li><li>Electronics production lines</li></ul><p>and other <strong>processes requiring gas evacuation or a vacuum environment</strong>.</p> </div>$h$, $h$Vacuum Pump | HD Marine$h$, $h$Vacuum pumps create negative pressure in a system by extracting the air or gas molecules within it. In this way, they deliver reliable performance in…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('e2377fe2-248f-5b1e-b9b3-84c6955028ba', 'd2a4f83b-27ee-5193-aa3e-20a6a11b7e91', 'en', $h$What is a vacuum pump?$h$, $h$<div> <p>A vacuum pump creates negative pressure by extracting air or gases from a system, providing a vacuum environment.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('1941a781-b560-5b6d-b897-2cd77417a363', '16db7546-bb0f-5158-b7ef-b45226a0a79f', 'en', $h$In which industries is it used?$h$, $h$<div> <p>It is widely used in industry, laboratories, production lines, packaging and chemical plants.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('a9e53e04-3b56-5362-9a92-7c29d2cfbbb6', 'b0dbb3e9-490b-55cd-a658-627f4ac38f89', 'en', $h$What is the difference between a vacuum pump and a pressure pump?$h$, $h$<div> <p>A vacuum pump draws air by creating negative pressure, whereas a pressure pump pushes the fluid.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d85fef8a-dd56-5c22-9102-6096c3779075', 'e33f2e87-834a-5d05-90f0-c6c8f495f4b8', 'en', $h$How often should a vacuum pump be maintained?$h$, $h$<div> <p>Periodic oil changes and leak checks are recommended depending on operating conditions.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('c4e3b252-d280-51ba-bda9-06e4b509510a', 'aa6ce44f-15fa-545f-b6b8-6a15f304eb00', 'en', $h$Dosing Pump$h$, $h$dosing-pump$h$, $h$Dosing Pump – A Precise and Reliable Liquid Dosing Solution$h$, $h$<div> <p><strong>Dosing pumps</strong> are high-precision industrial pumps designed to add a specific fluid to a system <strong>at a defined ratio and flow rate</strong>. They are frequently used in water treatment, chemicals, food production, wastewater processing and process control applications. Thanks to accurate dosing capability, they <strong>raise the quality of the manufactured product, reduce costs and increase process efficiency.</strong></p><p>HD Marine dosing pumps, with their <strong>adjustable flow control and durable construction</strong>, deliver stable and repeatable performance in industrial systems of every scale.</p> </div><div> <p>✔ <strong>High precision:</strong> Top-level consistency in the measured liquid quantity<br/>✔ <strong>Energy efficiency:</strong> Low energy consumption in long-term use<br/>✔ <strong>Easy maintenance:</strong> Fast servicing thanks to its modular design<br/>✔ <strong>Broad application compatibility:</strong> Flexible use for many industrial processes</p> </div>$h$, $h$<div> <p>HD Marine dosing pumps are used reliably in the following sectors:</p><ul><li><strong>Water and wastewater treatment plants</strong></li><li><strong>Chemical and petrochemical industry</strong></li><li><strong>Food and beverage production</strong></li><li><strong>Dyeing and textile processes</strong></li><li><strong>Heating, cooling and HVAC systems</strong></li><li><strong>Industrial process automation</strong></li></ul><p>These pumps deliver high accuracy in all applications requiring controlled and continuous dosing.</p> </div>$h$, $h$Dosing Pump | HD Marine$h$, $h$Dosing pumps are high-precision industrial pumps designed to add a specific fluid to a system at a defined ratio and flow rate . They are frequently used…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('c5f02ccb-50c9-5738-a988-6bd387f78053', 'bf9e337c-8d98-5214-8e62-0681c7b96ac4', 'en', $h$How does a diaphragm pump work?$h$, $h$<div> <p>A dosing pump is used to add a specific volume of liquid to a system in a controlled and adjustable manner.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d57939cc-c841-5ee5-8da3-6ccd1007f608', 'ac7f5894-09b2-5e43-acf3-646c592cee98', 'en', $h$In which sectors is it preferred?$h$, $h$<div> <p>It is widely used in water treatment, chemical production, food and beverage lines, wastewater and process control applications.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('63f1f1a5-aa8b-5ae7-bba0-3a700f2a6d8b', '62807921-7499-5ff7-8443-035b48b19ef3', 'en', $h$What is the difference between a dosing pump and a diaphragm pump?$h$, $h$<div> <p>A dosing pump is optimized for precise and adjustable liquid addition, while a diaphragm pump provides general positive displacement transfer.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('6a2927bb-27c5-5b05-b6e1-df4fb8a68de5', '0cb3652d-d4ed-5f21-9087-f6608c5b19ff', 'en', $h$How is the flow rate adjusted?$h$, $h$<div> <p>The desired flow rate can easily be selected via the control panel and adjustment knobs.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('a6a3814d-ffc2-5c78-85d4-2e1a94da1385', 'ee21040f-bed2-5a1d-bf45-784cfd019609', 'en', $h$Mono Pump$h$, $h$mono-pump$h$, $h$Mono Pump – Industrial Single-Stage Liquid Pump Solution$h$, $h$<div> <p>A <strong>mono pump</strong> is a type of <strong>single-stage centrifugal pump</strong> generally used in industrial facilities. It stands out with highly efficient liquid transfer, a simple design and low maintenance requirements. Mono pump models deliver reliable performance particularly in the handling of <strong>water, chemical solutions, oil and other fluids</strong>.</p><p>HD Marine mono pumps are a powerful aid in industrial processes thanks to their compact design, durable construction and <strong>high operating efficiency</strong>.</p> </div><div> <p>HD Marine mono pumps offer effective solutions in the following areas:</p><ul><li><strong>Water supply and discharge systems</strong></li><li><strong>Chemical transfer applications</strong></li><li><strong>Cooling systems</strong></li><li><strong>Paint and textile processes</strong></li><li><strong>Machine and equipment circuits</strong></li></ul><p>In these applications, the mono pump provides efficient and continuous liquid flow, contributing to the uninterrupted operation of processes.</p> </div><div> <p>📌 <strong>High efficiency:</strong> Effective energy use with a single-stage design</p><p>🛠 <strong>Easy maintenance:</strong> Servicing is simple and fast</p><p>🔧 <strong>Durability:</strong> Long-life construction with low operating costs</p><p>⚙ <strong>Various flow rate options:</strong> Wide capacity range from small to medium scale</p> </div>$h$, NULL, $h$Mono Pump | HD Marine$h$, $h$A mono pump is a type of single-stage centrifugal pump generally used in industrial facilities. It stands out with highly efficient liquid transfer, a…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d43917e4-ec19-5ff9-a635-e7d00bf9f709', 'cb553f18-f1e7-56c9-a4c3-535c3f9874aa', 'en', $h$What is a mono pump?$h$, $h$<div> <p>A mono pump is a liquid transfer pump operating on a single-stage centrifugal principle.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('6f5b0c58-bf41-5ee7-921e-913aefc3d330', 'd281d5ee-5e61-569b-9d92-36354f2995c8', 'en', $h$With which liquids is it used?$h$, $h$<div> <p>It is ideal for the transfer of fluids such as water, light chemical solutions, cooling and process water.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('959f3dbf-0ceb-543a-9954-7dd33370e5c1', '26ebb686-1a70-5558-8dc9-9b0fcef5df24', 'en', $h$What is the advantage of a mono pump?$h$, $h$<div> <p>Thanks to its simple design, it provides low maintenance requirements, high efficiency and durability.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('6c351489-4e12-5ba2-ae53-f332b5de6c38', '1263ce17-69af-5de0-99eb-7f1148fc4c36', 'en', $h$Who should choose it?$h$, $h$<div> <p>It is suitable for factories, industrial facilities, water transfer systems and process applications.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('f191018d-c864-51b9-a135-3b40abc83593', '58eca827-e60d-52b8-b970-af35ad0d0560', 'en', $h$Spiral Wound Steel Gasket$h$, $h$spiral-wound-steel-gasket$h$, $h$Spiral Wound Steel Gasket – Heavy-Duty Sealing Solution$h$, $h$<div> <p><strong>Spiral wound steel gaskets</strong> are industrial sealing elements that deliver <strong>superior sealing performance</strong> in high-pressure, high-temperature and demanding operating environments. The steel spiral winding structure, containing elastomer or graphite filler material, offers <strong>high strength, flexibility and recompression capability</strong>.</p><p>HD Marine spiral wound steel gaskets deliver long-lasting and reliable performance at <strong>flange connections</strong>, <strong>pipelines</strong>, <strong>pressure vessels</strong>, <strong>valves</strong> and other critical sealing points.</p> </div><div> <p>✔ <strong>High pressure resistance:</strong> Effective in heavy-duty applications<br/>✔ <strong>High temperature tolerance:</strong> Performance up to ±540°C<br/>✔ <strong>Mechanical strength:</strong> Superior resistance with a steel-wound structure<br/>✔ <strong>Flexible adaptation:</strong> Tolerates flange surface irregularities<br/>✔ <strong>Wide range of applications:</strong> Oil, chemical, energy and shipboard facilities</p> </div>$h$, $h$<div> <p>Spiral wound steel gaskets are used particularly in:</p><ul><li><strong>High-pressure pipelines</strong></li><li><strong>Steam and heat systems</strong></li><li><strong>Critical flange connections</strong></li><li><strong>Valve and pump bodies</strong></li><li><strong>Oil, chemical and energy plants</strong></li><li><strong>Ship and marine applications</strong></li></ul><p>and other industrial environments <strong>requiring high strength and sealing performance</strong>.</p> </div>$h$, $h$Spiral Wound Steel Gasket | HD Marine$h$, $h$Spiral wound steel gaskets are industrial sealing elements that deliver superior sealing performance in high-pressure, high-temperature and demanding…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('ab11d978-ce90-5ce4-a4c6-2956935cbd50', 'ac4b029f-02ee-5028-a858-4aa0379f453c', 'en', $h$What is a spiral wound steel gasket?$h$, $h$<div> <p>A spiral wound steel gasket is an industrial gasket that provides sealing at high pressure through a steel wire spiral structure and elastomer / graphite filler.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('eb81cf97-3e08-5ac8-89c8-ac853578fffa', '45c335ce-cbb2-5409-912b-d69e32a70f88', 'en', $h$In which applications is it used?$h$, $h$<div> <p>It is preferred in flange connections, pipelines, valves, pressurized systems and high-temperature applications.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('3e4f141e-9725-5e7d-924e-4da91a809228', 'ffe0ce1a-4ce4-5235-9705-f879c84ca453', 'en', $h$What does the graphite filler do?$h$, $h$<div> <p>The graphite filler provides high temperature and chemical resistance, and increases the gasket's flexible adaptation.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('b87cb07e-a41b-563c-9b84-80ba2504402d', '20593174-28d9-5f31-9d10-4f339aed7dff', 'en', $h$Why is the steel material type important?$h$, $h$<div> <p>Stainless steels such as AISI 304 and AISI 316 provide long life and resistance in corrosive environments.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('f873bafb-f0ea-520d-98be-cdee61b22adb', '5992167a-bbd3-580f-8470-ac9929c461ec', 'en', $h$Graphite and Klingerite Gaskets$h$, $h$graphite-and-klingerite-gaskets$h$, $h$Graphite & Klingerite Gaskets – High-Performance Sealing Elements$h$, $h$<div> <p><strong>Graphite and klingerite gaskets</strong> are critical sealing solutions used in pipelines, flange connections, valves and industrial equipment to provide <strong>sealing against high temperature, high pressure and aggressive chemicals</strong>. These gaskets are manufactured from special graphite alloy materials and fiber-reinforced compositions, and deliver reliable performance in demanding processes.</p><p>Graphite gaskets are produced from pure or reinforced graphite material and are preferred particularly in high-heat, steam, oil, water and gas applications. This structure gives the material both <strong>high chemical resistance</strong> and <strong>temperature tolerance</strong>.</p><p>Klingerite gaskets are typically formed by pressing graphite- or fiber-based mixtures, and provide sealing to industrial standards with asbestos-free options.</p> </div><div> <p>✔ <strong>High temperature resistance</strong> – Suitable for steam and superheated environments (performance over a wide temperature range) <br/>✔ <strong>Strong sealing against pressure</strong> – Creates an effective seal at flange, valve and pipe joint connections <br/>✔ <strong>Chemical resistance</strong> – Resistant to oils, acids, alkaline solutions and solvents <br/>✔ <strong>Flexible conformity</strong> – Fills surface irregularities for effective gasket performance <br/>✔ <strong>Asbestos-free production</strong> – Manufactured with alternatives that meet modern sealing requirements and are harmless to human health</p> </div>$h$, $h$<div> <p>Graphite and klingerite gaskets are used effectively in the following applications:</p><ul><li>Flange connections and pipelines</li><li>Valve covers and pump bodies</li><li>Steam systems and high-temperature processes</li><li>Chemical, petrochemical and energy plants</li><li>Marine and industrial piping circuits</li></ul><p>These gaskets are sealing elements preferred particularly for <strong>high temperature, high pressure and aggressive environments</strong>.</p> </div>$h$, $h$Graphite and Klingerite Gaskets | HD Marine$h$, $h$Graphite and klingerite gaskets are critical sealing solutions used in pipelines, flange connections, valves and industrial equipment to provide sealing…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('b8e6be5b-3421-56fd-bce2-eba81c1a0421', '14ed46ed-c461-597c-ac43-cbedb3ac3d5b', 'en', $h$What is a graphite gasket?$h$, $h$<div> <p>A graphite gasket is a graphite-based gasket type that provides effective sealing at high temperature and pressure; it is resistant to aggressive chemicals.</p> </div>$h$) ON CONFLICT DO NOTHING;
